var a=`0418-barmbrack`;var i=`world-0418`;var t=`IE`;var o=`northern-europe`;var r=8;var s=196;var l={en:`Barmbrack`,ua:`Бармбрек`};var g={en:`A traditional dish from Ireland, centered on raisin, sultana, all-purpose flour, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: родзинки, кишмиш сушений, пшеничне борошно універсальне, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Steep raisins and sultanas in brewed black tea for two hours to plump them, then keep the soaking liquid for the cake.`,ua:`Замочіть родзинки та кишмиш у завареному чорному чаї на дві години; рідину збережіть для тіста.`,t:[`soaking-legumes`],m:120,i:[[`raisin`,150,`g`],[`sultana`,90,`g`],[`black-tea`,280,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`all-purpose-flour`,340,`g`],[`brown-sugar`,120,`g`],[`chicken-egg`,1,`pcs`],[`baking-powder`,10,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:4,i:[]},{en:`Bake in a preheated 180°C oven for about 65 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 65 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:65,i:[]}];var d={slug:a,id:i,country:`IE`,region:o,servings:8,minutes:196,title:l,text:g,steps:u};export{t as country,d as default,i as id,s as minutes,o as region,r as servings,a as slug,u as steps,g as text,l as title};